mapper.select:
SELECT p.id, p.asset_id, da.name AS asset_name, da.category_id, p.type, p.name,
       p.platform_name, p.price, p.shipping_cost, p.purchase_date
FROM purchase p
JOIN device_asset da ON da.id = p.asset_id

    AND p.purchase_date >= #{dateFrom}
    AND p.purchase_date <= #{dateTo}

        AND (da.category_id = #{categoryId}
             OR CONCAT(da.category_path, '/') LIKE CONCAT('%/', #{categoryId}, '/%'))

    AND p.type = #{type}
    AND p.platform_id = #{platformId}

        AND (da.name LIKE CONCAT('%', #{keyword}, '%')
             OR da.brand LIKE CONCAT('%', #{keyword}, '%')
             OR da.model LIKE CONCAT('%', #{keyword}, '%')
             OR p.name LIKE CONCAT('%', #{keyword}, '%')
             OR p.seller LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY p.purchase_date DESC, p.id DESC
